SELECT  FROM macro_monthly
WHERE indicator_code = #{indicatorCode}
  AND stat_date >= #{startDate} AND stat_date <= #{endDate}
  AND data_version = #{dataVersion}
ORDER BY stat_date ASC

SELECT  FROM macro_monthly
WHERE indicator_code IN

  #{code}

  AND stat_date >= #{startDate} AND stat_date <= #{endDate}
ORDER BY stat_date ASC, indicator_code ASC

SELECT  FROM macro_monthly
WHERE stat_date = #{statDate} AND indicator_code = #{indicatorCode} AND data_version = #{dataVersion}
LIMIT 1
